look.customCSS:
/* ───── 雨天窗边 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/90px 120px repeat,url("data:image/svg+xml;base64,") 0 0/390px 420px repeat,linear-gradient(180deg,#C7DBFF,#E9F1FF 45%,#FCEBFA) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一截白窗框，下沿一条木窗台 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:#FFFFFF !important;border-bottom:none !important;box-shadow:0 3px 0 #FFC6DE !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:-12px !important;height:10px !important;background:radial-gradient(circle at 10px 0,#FFC6DE 9px,transparent 9.5px) 0 0/20px 10px repeat-x !important;pointer-events:none !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:10px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#3A4A6B !important}
[data-wk="headdim"]{color:#8C9BC0 !important;white-space:nowrap !important}
[data-wk="chatback"] svg{stroke:#3A4A6B !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/21px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PGNpcmNsZSBjeD0nNScgY3k9JzEyJyByPScxLjUnIGZpbGw9JyMzQTRBNkInLz48Y2lyY2xlIGN4PScxMicgY3k9JzEyJyByPScxLjUnIGZpbGw9JyMzQTRBNkInLz48Y2lyY2xlIGN4PScxOScgY3k9JzEyJyByPScxLjUnIGZpbGw9JyMzQTRBNkInLz48L3N2Zz4=") center/21px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆，一圈白窗框 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 2.5px #FFFFFF,0 0 0 4px #FFC6DE !important}

/* 我的话：起雾的玻璃，右上挂两颗水珠 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;color:#3A4A6B !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(160deg,rgba(255,255,255,.7),rgba(255,255,255,0) 40%),linear-gradient(135deg,#BFDDFF,#E3D4FF) !important;border:1.4px solid #fff !important;border-radius:18px 18px 4px 18px !important;box-shadow:0 0 0 1.2px #7FA6E8,0 4px 10px rgba(91,141,239,.22) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;right:6px !important;top:-7px !important;left:auto !important;bottom:auto !important;width:24px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:none !important}
/* 他的话：窗边一张白便条，左上斜着一道窗框的影子 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(125deg,rgba(199,219,255,.5) 0 14px,transparent 14px),#FFFFFF !important;border:1.4px solid #FFC6DE !important;border-radius:18px 18px 18px 4px !important;box-shadow:0 4px 10px rgba(246,150,190,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;right:-6px !important;top:-8px !important;left:auto !important;bottom:auto !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTEyIDIgTDE0LjYgOS40IEwyMiAxMiBMMTQuNiAxNC42IEwxMiAyMiBMOS40IDE0LjYgTDIgMTIgTDkuNCA5LjRaJyBmaWxsPScjRkZFOUE4JyBzdHJva2U9JyNFOUI5NDknIHN0cm9rZS13aWR0aD0nMS4yJyBzdHJva2UtbGluZWpvaW49J3JvdW5kJy8+PC9zdmc+") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="msg"][data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before,[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:none !important}

/* 时间：雾里的一行小字，两边一短横 */
[data-wk="time"] > span{min-width:150px !important;background:transparent !important;border:none !important;color:#8C9BC0 !important;font-size:11px !important;letter-spacing:.12em !important}
[data-wk="time"] > span::before{content:"— " !important}
[data-wk="time"] > span::after{content:" —" !important}
/* 已读：一颗小水滴；已送达一行小字 */
[data-wk="meta"]{color:#8C9BC0 !important;font-size:10.5px !important}
[data-wk="meta"][data-read="1"]{font-size:0 !important;width:11px !important;height:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"] *{opacity:0 !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFFFF !important;border:1.4px solid #7FA6E8 !important;border-radius:16px 16px 16px 4px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#5B8DEF !important}

/* 动描：像写在起雾玻璃上的字——没有框，左边一道往下流的水痕 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:transparent !important;border:none !important;box-shadow:none !important;color:#3A4A6B !important;opacity:.72 !important;font-style:italic !important;font-size:13px !important;padding-left:14px !important;border-left:2px solid transparent !important;border-image:linear-gradient(180deg,#5B8DEF,rgba(111,147,176,0)) 1 !important;border-radius:0 !important}
/* 系统提示：不带框的一行小字，前面一把小伞 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#8C9BC0 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.06em !important}
[data-wk="sysnotetext"]::before{content:"☂ " !important}

/* 底栏：白窗框＋上沿一条窗台，左发送右回复 */
[data-wk="composer"]{background:#FFFFFF !important;border-top:none !important;box-shadow:0 -3px 0 #FFC6DE !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#F2F7FF !important;border:1.4px solid #7FA6E8 !important;border-radius:14px !important;color:#3A4A6B !important}
[data-wk="chatinput"]::placeholder{color:#8C9BC0 !important}
[data-wk="chatplus"],[data-wk="send"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/23px no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{position:relative !important;width:64px !important;min-width:64px !important;height:34px !important;border:none !important;border-radius:17px !important;background:linear-gradient(135deg,#7FB0FF,#B79CFF) !important;box-shadow:0 3px 8px rgba(91,141,239,.3) !important}
[data-wk="chatreply"]::before{content:"回复" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;color:#fff !important;font-size:13px !important;letter-spacing:.15em !important;padding-left:14px !important}
[data-wk="chatreply"]::after{content:"" !important;position:absolute !important;left:9px !important;top:50% !important;width:14px !important;height:14px !important;margin-top:-7px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
